test('Flee ends combat without granting victory XP', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  App.worldMeta = { seed: 'flee-success', generatorVersion: 2 };
  const player = makeUnit('You', { id: 'player-1', Flee: 50, xp: 0, xpToNext: 100 });
  const enemy = makeUnit('Enemy', { id: 'enemy-1', disposition: App.DISPOSITION.ENEMY, spd: 1 });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy];
  App.location = { x: 0, y: 0 };
  App.dayCount = 0;
  App.timeHour = 0;
  App.combatState = { active: true, round: 1, currentTurn: 0, turnQueue: [{ unit: player, initiative: 20 }, { unit: enemy, initiative: 10 }], syncActions: [] };
  App.activeActor = player;
  App.updateLanguage('es');
  App.showActorActions(player);
  assertContains(elements.get('desktop-context-belt').innerHTML, "executeCombatIntent('fight')", 'Desktop combat composer should expose combat actions before fleeing');
  App.attemptFlee();
  assertEqual(App.combatState.active, false, 'Flee should end combat');
  assertEqual(player.xp, 0, 'Flee should not grant victory XP');
  assertContains(App.log[0].text, 'Huyes con exito!', 'Successful flee log should localize');
  assertNotContains(elements.get('desktop-context-belt').innerHTML, "executeCombatIntent('fight')", 'Flee should remove stale combat actions from the desktop composer');
  assertContains(elements.get('party-content').innerHTML, 'Agregar You como actor', 'Flee should restore effective player fallback without showing explicit actor selection');
  assertNotContains(elements.get('party-content').innerHTML, 'Now #', 'Flee should remove stale turn-order badges');
});

test('Flee failure and no-enemy feedback localize', () => {
  const empty = loadAppForCombat(() => 0);
  empty.App.player = makeUnit('You', { Flee: 10 });
  empty.App.party = [empty.App.player];
  empty.App.creatures = [];
  empty.App.updateLanguage('es');
  empty.App.attemptFlee();
  assertContains(empty.App.log[empty.App.log.length - 1].text, 'No hay enemigos de los que huir!', 'No-enemy flee log should localize');

  const failed = loadAppForCombat(() => 1);
  failed.App.worldMeta = { seed: 'flee-fail', generatorVersion: 2 };
  const player = makeUnit('You', { id: 'player-1', Flee: 1 });
  const enemy = makeUnit('Fast Enemy', { id: 'enemy-1', disposition: failed.App.DISPOSITION.ENEMY, spd: 50 });
  failed.App.player = player;
  failed.App.party = [player];
  failed.App.creatures = [enemy];
  failed.App.location = { x: 0, y: 0 };
  failed.App.dayCount = 0;
  failed.App.timeHour = 0;
  failed.App.combatState = { active: true, round: 1, currentTurn: 0, turnQueue: [], syncActions: [] };
  failed.App.targetSelection = { action: 'fight', source: 'combat', actorId: 'player-1' };
  failed.App.syncSelection = { active: true, phase: 'choose', actorId: 'player-1', participantIds: ['player-1'], type: null };
  failed.App.feedSelection = { active: true, actorId: 'player-1', subIds: ['heal'] };
  failed.App.nextTurn = function() { this._fleeFailedTurnEnded = true; };
  failed.App.updateLanguage('es');
  failed.App.attemptFlee();
  assertEqual(failed.App._fleeFailedTurnEnded, true, 'Failed flee should still advance the turn');
  assertEqual(failed.App.targetSelection, null, 'Failed flee should clear stale target selection');
  assertEqual(failed.App.syncSelection, null, 'Failed flee should clear stale sync selection');
  assertEqual(failed.App.feedSelection, null, 'Failed flee should clear stale feed selection');
  assertContains(failed.App.log[failed.App.log.length - 1].text, 'Huida fallida! Fast Enemy te intercepta!', 'Failed flee log should localize');
});

test('Player flee result is deterministic by combat state', () => {
  const buildCase = random => {
    const { App } = loadAppForCombat(random);
    App.worldMeta = { seed: 'player-flee', generatorVersion: 2 };
    const player = makeUnit('You', { id: 'player-1', Flee: 20, xp: 0, xpToNext: 100 });
    const enemy = makeUnit('Enemy', { id: 'enemy-1', disposition: App.DISPOSITION.ENEMY, spd: 20 });
    App.player = player;
    App.party = [player];
    App.creatures = [enemy];
    App.location = { x: 0, y: 0 };
    App.dayCount = 0;
    App.timeHour = 0;
    App.combatState = { active: true, round: 1, currentTurn: 0, turnQueue: [], syncActions: [] };
    App.nextTurn = function() { this._fleeAdvanced = true; };
    App.attemptFlee();
    return { active: App.combatState.active, enemies: App.creatures.length, advanced: !!App._fleeAdvanced, log: App.log[0]?.type || '' };
  };
  const lowRandom = buildCase(() => 0);
  const highRandom = buildCase(() => 0.99);
  assertEqual(JSON.stringify(lowRandom), JSON.stringify(highRandom), 'Player flee result should not depend on ambient Math.random');
});

test('Combat social action ratings are deterministic by combat state', () => {
  const buildCase = (random, action) => {
    const { App } = loadAppForCombat(random);
    App.worldMeta = { seed: `combat-social-${action}`, generatorVersion: 2 };
    const player = makeUnit('You', { id: 'player-social' });
    const actor = makeUnit('Ally', { id: `actor-${action}`, Fuck: 60, Flir: 60, cha: 18 });
    const target = makeUnit('Enemy', { id: `target-${action}`, disposition: App.DISPOSITION.ENEMY, CPle: action === 'fuck' ? 70 : 0, MPle: 100, wis: 1 });
    App.player = player;
    App.party = [player, actor];
    App.creatures = [target];
    App.location = { x: 2, y: -1 };
    App.dayCount = 1;
    App.timeHour = 11;
    App.combatState = { active: true, round: 2, currentTurn: 1, processing: false, xpEarned: 0, turnQueue: [{ unit: actor, initiative: 10 }], syncActions: [] };
    App.nextTurn = function() { this._socialAdvanced = true; };
    App.executeActionAgainstTarget(action, actor, target);
    return { pleasure: target.CPle, disposition: target.disposition, advanced: !!App._socialAdvanced, log: App.log.map(entry => entry.text).join('|') };
  };
  for (const action of ['flirt', 'fuck']) {
    assertEqual(JSON.stringify(buildCase(() => 0, action)), JSON.stringify(buildCase(() => 0.99, action)), `Combat ${action} rating should not depend on ambient Math.random`);
  }
});

