test('Core gameplay loop can move fight loot save and reload state', () => {
  const Binary = loadBinaryForTest();
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-e2e', Figh: 80, spd: 100, xp: 0, xpToNext: 1000, gold: 0 });
  const enemy = makeUnit('Hostile Guide', {
    id: 'hostile-guide-e2e',
    disposition: App.DISPOSITION.ENEMY,
    CPun: 1,
    MPun: 20,
    con: 1,
    spd: 1,
    goldLoot: 3
  });
  App.worldMeta = { worldId: 'e2e-world', seed: 'e2e-seed', generatorVersion: 2, mapModsHash: 'core' };
  App.player = player;
  App.party = [player];
  App.creatures = [];
  App.inventory = [];
  App.log = [];
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'grove';
  App.timeHour = 8;
  App.dayCount = 0;
  App.quests = [];
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  App.exploredTiles = new Set(['0,0', '1,0']);
  App.worldMap.set('0,0', { ...App.getBaseTile(0, 0), explored: true, biome: 'grove', description: 'Origin', creatures: [], items: [] });
  App.worldMap.set('1,0', { ...App.getBaseTile(1, 0), explored: true, biome: 'grove', description: 'Encounter tile', creatures: [enemy], items: [] });

  App.move(1, 0);
  assertEqual(App.combatState.active, true, 'Moving into an explored hostile tile should start combat');
  assertEqual(App.location.x, 1, 'Movement should update x coordinate');
  assertEqual(App.location.y, 0, 'Movement should update y coordinate');
  assertEqual(App.creatures[0].id, 'hostile-guide-e2e', 'Encounter creature should be restored from the destination tile');

  App.executeAction('fight', 0);
  assertEqual(App.combatState.active, false, 'One-hit victory should end combat');
  assertEqual(App.creatures[0].disposition, App.DISPOSITION.CORPSE, 'Defeated creature should become a corpse');
  assertEqual(App.lootCorpse('hostile-guide-e2e'), true, 'Corpse should be lootable after combat');
  assertEqual(App.player.gold, 3, 'Authored corpse gold should be awarded during loot');

  const saved = Binary.saveGame(App);
  const loaded = Binary.loadGame(saved);
  assertEqual(loaded.locationX, 1, 'Saved state should preserve current x coordinate');
  assertEqual(loaded.locationY, 0, 'Saved state should preserve current y coordinate');
  assertEqual(loaded.questState.playerGold, 3, 'Saved state should preserve looted gold');
  assertEqual(loaded.worldMap['1,0'].creatures[0].disposition, App.DISPOSITION.CORPSE, 'Saved world tile should preserve corpse disposition');
  assertEqual(loaded.worldMap['1,0'].creatures[0].looted, true, 'Saved world tile should preserve corpse loot state');
});

asyncTest('Safe-created character save/load keeps compatibility fields hidden in safe tier', async () => {
  const Binary = loadBinaryForTest();
  const savedBuffers = new Map();
  const created = loadAppForCombat(() => 0.5, { binary: Binary });
  created.document.getElementById('char-name').value = 'Safe Tester';
  created.App.setContentTier('safe');
  created.App.selectSpecies('human');
  created.App.selectGender('female');
  created.App.createCharacter();

  assertEqual(created.App.screen, 'game', 'Safe character creation should enter the game screen');
  assertEqual(created.App.player.parts, 'clit', 'Safe-created player should keep hidden compatibility primary field');
  assertEqual(created.App.player.chest, 'tits', 'Safe-created player should keep hidden compatibility chest field');
  created.App.persistWorldStateToMapStore = async () => { throw new Error('force inline world map'); };
  created.App._dbPut = async (_store, key, value) => { savedBuffers.set(key, value); };
  const saved = await created.App._saveToSlotConfirmed('slot1');
  assertEqual(saved, true, 'Safe-created character should save successfully');

  const loaded = loadAppForCombat(() => 0.5, { binary: Binary });
  loaded.App._dbGet = async (_store, key) => savedBuffers.get(key) || null;
  loaded.App.loadWorldStateFromMapStore = async () => {};
  loaded.App.setContentTier('safe');
  const restored = await loaded.App.loadFromSlot('slot1');
  assertEqual(restored, true, 'Safe-created character should load successfully');
  assertEqual(loaded.App.player.name, 'Safe Tester', 'Loaded safe-created player should preserve name');
  assertEqual(loaded.App.player.parts, 'clit', 'Loaded safe-created player should preserve hidden compatibility primary field');
  assertEqual(loaded.App.player.chest, 'tits', 'Loaded safe-created player should preserve hidden compatibility chest field');

  loaded.App.showCharacterStats();
  const safeStatsHtml = loaded.elements.get('party-content').innerHTML;
  assertNotContains(safeStatsHtml, 'Body Type:', 'Loaded safe-tier stats should not reveal compatibility body type');
  assertNotContains(safeStatsHtml, 'Chest Type:', 'Loaded safe-tier stats should not reveal compatibility chest type');
  const inspectTarget = makeUnit('Safe Inspect Target', { id: 'loaded-safe-inspect', disposition: loaded.App.DISPOSITION.FRIENDLY, parts: 'cock', chest: 'tits' });
  loaded.App.creatures = [inspectTarget];
  loaded.App.outsideActionForCreature('inspect', 'loaded-safe-inspect');
  assertNotContains(loaded.App.log[loaded.App.log.length - 1].text, 'Body Type:', 'Loaded safe-tier inspect should not reveal compatibility body type');
  assertNotContains(loaded.App.log[loaded.App.log.length - 1].text, 'Chest Type:', 'Loaded safe-tier inspect should not reveal compatibility chest type');

  loaded.App.setContentTier('adult');
  loaded.App.showCharacterStats();
  assertContains(loaded.elements.get('party-content').innerHTML, 'Body Type:', 'Adult tier after load should reveal explicit body detail fields');
  loaded.App.outsideActionForCreature('inspect', 'loaded-safe-inspect');
  assertContains(loaded.App.log[loaded.App.log.length - 1].text, 'Body Type:', 'Adult tier after load should reveal explicit inspect fields');
});

test('Active tile creature damage and combat state survive save and load', async () => {
  const Binary = loadBinaryForTest();
  const savedBuffers = [];
  const { App, hooks } = loadAppForCombat(() => 0.5, { binary: Binary });
  const player = makeUnit('You', { id: 'player-save-combat', Figh: 20 });
  const enemy = makeUnit('Ratfolk', {
    id: 'enemy-save-combat',
    disposition: App.DISPOSITION.ENEMY,
    CPun: 17,
    MPun: 43,
    Flee: 1
  });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy];
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'grove';
  App.worldMeta = { worldId: 'combat-save-world', seed: 'combat-save-seed', generatorVersion: 2, mapModsHash: 'core' };
  App.worldMap = new Map([['0,0', { ...App.getBaseTile(0, 0), explored: true, biome: 'grove', creatures: [enemy], items: [] }]]);
  App.tileDeltas = new Map();
  App.exploredTiles = new Set(['0,0']);
  App.combatState = {
    active: true,
    round: 2,
    currentTurn: 0,
    processing: false,
    xpEarned: 15,
    turnQueue: [{ unit: player, initiative: 20 }, { unit: enemy, initiative: 10 }],
    syncActions: []
  };
  App.activeActor = player;
  App.persistWorldStateToMapStore = async () => { throw new Error('force inline world map'); };
  App._dbPut = async (_store, _key, value) => { savedBuffers.push(value); };

  const saved = await App._saveToSlotConfirmed('slot1');
  assertEqual(saved, true, 'Manual save should complete');
  const saveHook = hooks.find(hook => hook.event === 'onGameSave');
  assert(saveHook, 'Manual save should emit onGameSave');
  assertEqual(saveHook.payload.slotName, 'slot1', 'Save hook should include the saved slot');
  assertEqual(saveHook.payload.auto, false, 'Manual save hook should distinguish non-auto saves');
  assertEqual(saveHook.payload.combatActive, true, 'Save hook should report active combat state');
  const loaded = Binary.loadGame(savedBuffers[0]);
  assertEqual(loaded.worldMap['0,0'].creatures[0].CPun, 17, 'Saved current tile creature should keep damaged punishment');
  assertEqual(loaded.worldMap['0,0'].creatures[0].MPun, 43, 'Saved current tile creature should keep max punishment');
  assertEqual(loaded.questState.combatState.active, true, 'Save metadata should preserve active combat');
  assertEqual(loaded.questState.combatState.currentTurn, 0, 'Save metadata should preserve current turn index');

  const loadedApp = loadAppForCombat(() => 0.5, { binary: Binary });
  loadedApp.App._dbGet = async () => savedBuffers[0];
  loadedApp.App.loadWorldStateFromMapStore = async () => {};
  const restored = await loadedApp.App.loadFromSlot('slot1');
  assertEqual(restored, true, 'Saved combat slot should load');
  const loadHook = loadedApp.hooks.find(hook => hook.event === 'onGameLoad');
  assert(loadHook, 'Successful load should emit onGameLoad');
  assertEqual(loadHook.payload.slotName, 'slot1', 'Load hook should include the loaded slot');
  assertEqual(loadHook.payload.combatActive, true, 'Load hook should report restored combat state');
  assertEqual(loadHook.payload.location.x, 0, 'Load hook should include restored location metadata');
  assertEqual(loadedApp.App.creatures[0].CPun, 17, 'Loaded active tile enemy should keep damaged punishment');
  assertEqual(loadedApp.App.combatState.active, true, 'Loaded active combat should remain in combat mode');
  assertEqual(loadedApp.App.mode, loadedApp.App.GAME_MODE.COMBAT, 'Loaded active combat should restore combat game mode');
  assertEqual(loadedApp.App.combatState.turnQueue[1].unit.id, 'enemy-save-combat', 'Loaded combat queue should point at restored enemy object');
});

