test('Single-target exploration wrappers return resolver outcomes', () => {
  const { App } = loadAppForCombat(() => 0);
  const actor = makeUnit('Actor', { id: 'actor-1', Flir: 30, cha: 20 });
  const partyTarget = makeUnit('Party Target', { id: 'party-target', CPle: 0, MPle: 100, wis: 1 });
  const creatureTarget = makeUnit('Creature Target', { id: 'creature-target', disposition: App.DISPOSITION.FRIENDLY, CPle: 0, MPle: 100, wis: 1 });
  App.player = actor;
  App.party = [actor, partyTarget];
  App.creatures = [creatureTarget];
  assertEqual(App.outsideActionForParty('flirt', 1), true, 'Party wrapper should report successful single-target resolution');
  assert(partyTarget.CPle > 0, 'Successful party wrapper action should affect target');
  assertEqual(App.outsideActionForCreature('flirt', 'creature-target'), true, 'Creature wrapper should report successful single-target resolution');
  assert(creatureTarget.CPle > 0, 'Successful creature wrapper action should affect target');
  assertEqual(App.outsideActionForParty('flirt', 99), false, 'Party wrapper should report missing target failure');
  assertEqual(App.outsideActionForCreature('flirt', 'missing-creature'), false, 'Creature wrapper should report missing target failure');
  assertEqual(App.outsideActionForCreatureAs('missing-actor', 'flirt', 'missing-creature'), false, 'Actor-specific creature wrapper should report missing target failure');
  const creaturePleAfterValidActor = creatureTarget.CPle;
  assertEqual(App.outsideActionForCreatureAs('missing-actor', 'flirt', 'creature-target'), false, 'Actor-specific creature wrapper should report stale actor failure');
  assertEqual(creatureTarget.CPle, creaturePleAfterValidActor, 'Stale actor wrapper should not mutate the target through player fallback');
});

test('Composer tray and intent menu use one adventure interaction dispatcher', () => {
  const setup = () => {
    const { App } = loadAppForCombat(() => 0);
    const player = makeUnit('You', { id: 'player-1', CPle: 0, MPle: 100, wis: 1 });
    const actor = makeUnit('Goatfolk', { id: 'goat-1', Fuck: 80, Flir: 60, cha: 20 });
    App.player = player;
    App.party = [player, actor];
    App.explorationActorIds = ['goat-1'];
    return { App, player, actor };
  };
  const tray = setup();
  tray.App.toggleExplorationTarget('party', 'player-1');
  assertEqual(tray.App.resolveExplorationTargetAction('fuck', 'seduce', 'composer-tray'), true, 'Composer tray route should resolve the selected actor against the selected target');
  assert(tray.player.CPle > 0, 'Composer tray route should affect the selected party target');
  assertEqual(tray.App.lastIntentCommand.source, 'composer-tray', 'Composer tray route should record the composer command source');
  assertEqual(tray.App.lastIntentCommand.actorIds.join(','), 'goat-1', 'Composer tray route should record the selected actor');
  assertEqual(tray.App.lastIntentCommand.targetIds.join(','), 'player-1', 'Composer tray route should record the selected target');

  const legacyTray = setup();
  legacyTray.App.toggleExplorationTarget('party', 'player-1');
  assertEqual(legacyTray.App.resolveExplorationTargetAction('fuck', 'seduce', 'panel-tray'), true, 'Legacy panel-tray source should remain a valid composer alias');
  assertEqual(legacyTray.App.lastIntentCommand.source, 'composer-tray', 'Legacy panel-tray source should normalize to composer-tray metadata');

  const menu = setup();
  assertEqual(menu.App.selectIntent('party', 0, 'fuck', 'sheet', 'seduce'), true, 'Intent menu route should resolve through the same dispatcher');
  assert(menu.player.CPle > 0, 'Intent menu route should affect the same party target');
  assertEqual(menu.App.lastIntentCommand.actorIds.join(','), 'goat-1', 'Intent menu route should record the selected actor');
  assertEqual(menu.App.lastIntentCommand.targetIds.join(','), 'player-1', 'Intent menu route should record the selected target');
  assertContains(menu.App.log[menu.App.log.length - 1].text, 'Goatfolk', 'Intent menu route should log the selected actor, not fall back to player');

  const fallback = setup();
  fallback.App.toggleExplorationTarget('party', 'player-1');
  assertEqual(fallback.App._dispatchPanelInteraction({
    mode: 'adventure',
    actors: [fallback.actor],
    targets: [fallback.player],
    action: 'flirt'
  }), true, 'Unspecified panel dispatch should still resolve through the shared adventure dispatcher');
  assertEqual(fallback.App.lastIntentCommand.source, 'command-composer', 'Unspecified panel dispatch should record the command composer as the source of truth');
});

