test('Panel wrappers use one command dispatcher for adventure interactions', () => {
  const { App } = loadAppForCombat(() => 0);
  const actor = makeUnit('Actor', { id: 'actor-panel-dispatch', Flir: 30, cha: 20 });
  const partyTarget = makeUnit('Party Target', { id: 'party-panel-dispatch' });
  const creatureTarget = makeUnit('Creature Target', { id: 'creature-panel-dispatch', disposition: App.DISPOSITION.FRIENDLY });
  App.player = actor;
  App.party = [actor, partyTarget];
  App.creatures = [creatureTarget];
  App.explorationActorIds = ['actor-panel-dispatch'];
  const seen = [];
  const originalDispatch = App._dispatchInteractionCommand.bind(App);
  App._dispatchInteractionCommand = command => {
    seen.push({
      mode: command.mode,
      action: command.action,
      source: command.source,
      actorIds: command.actorIds,
      targetIds: command.targetIds,
      targetType: command.targetType
    });
    return originalDispatch(command);
  };
  assertEqual(App.outsideActionForParty('flirt', 1), true, 'Party wrapper should resolve through shared panel dispatch');
  assertEqual(App.outsideActionForCreature('flirt', 'creature-panel-dispatch'), true, 'Creature wrapper should resolve through shared panel dispatch');
  assertEqual(App.outsideAction('flirt', 'party', 0), true, 'Filtered-index party compatibility wrapper should still resolve');
  assertEqual(App.outsideAction('flirt', 'creature', 0), true, 'Filtered-index creature compatibility wrapper should still resolve');
  App.toggleExplorationTarget('party', 'party-panel-dispatch');
  assertEqual(App.resolveExplorationTargetAction('feed', 'heal', 'composer-tray'), true, 'Marked-target tray should resolve through shared panel dispatch');
  assertEqual(seen.length, 5, 'Each panel interaction route should hit the same dispatcher once');
  assertEqual(seen[0].source, 'command-composer', 'Party wrapper should route through command composer provenance');
  assertEqual(seen[0].targetType, 'party', 'Party wrapper should preserve target type');
  assertEqual(seen[1].source, 'command-composer', 'Creature wrapper should route through command composer provenance');
  assertEqual(seen[1].targetIds[0], 'creature-panel-dispatch', 'Creature wrapper should resolve target id through command metadata');
  assertEqual(seen[2].source, 'command-composer', 'Filtered-index party compatibility wrapper should delegate to the command composer');
  assertEqual(seen[3].source, 'command-composer', 'Filtered-index creature compatibility wrapper should delegate to the command composer');
  assertNotContains(seen.map(entry => entry.source).join(','), 'wrapper', 'Filtered-index compatibility wrappers should not emit legacy wrapper command sources');
  assertEqual(seen[4].source, 'composer-tray', 'Marked target tray should keep source metadata');
  assertEqual(seen[4].targetType, 'marked', 'Marked target tray should preserve marked target type');
});

test('Panel wrappers use one command dispatcher for combat target clicks', () => {
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-combat-panel-dispatch', Figh: 60 });
  const enemy = makeUnit('Enemy', { id: 'enemy-combat-panel-dispatch', disposition: App.DISPOSITION.ENEMY, CPun: 80, con: 1 });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy];
  App.combatState = {
    active: true,
    round: 1,
    currentTurn: 0,
    processing: false,
    xpEarned: 0,
    turnQueue: [{ unit: player, initiative: 20 }, { unit: enemy, initiative: 10 }],
    syncActions: []
  };
  App.activeActor = player;
  App.nextTurn = function() {};
  const seen = [];
  const originalDispatch = App._dispatchInteractionCommand.bind(App);
  App._dispatchInteractionCommand = command => {
    seen.push({
      mode: command.mode,
      action: command.action,
      source: command.source,
      actorIds: command.actorIds,
      targetIds: command.targetIds
    });
    return originalDispatch(command);
  };
  App.selectTarget('fight');
  assertEqual(App.executeActionOnTarget('fight', 'enemy-combat-panel-dispatch'), true, 'Combat target card should resolve through shared panel dispatch');
  assertEqual(seen.length, 1, 'Combat target click should hit the same dispatcher once');
  assertEqual(seen[0].mode, 'combat', 'Combat target click should build a combat command');
  assertEqual(seen[0].source, 'combat-targeting', 'Combat target click should identify the combat target-picker command surface');
  assertEqual(seen[0].actorIds[0], 'player-combat-panel-dispatch', 'Combat command should record active actor id');
  assertEqual(seen[0].targetIds[0], 'enemy-combat-panel-dispatch', 'Combat command should record clicked target id');

  enemy.CPun = 80;
  App.combatState.processing = false;
  App.combatState.currentTurn = 0;
  App.targetSelection = null;
  assertEqual(App.executeAction('fight', 0), true, 'Legacy filtered-index combat wrapper should still resolve');
  assertEqual(seen.length, 2, 'Legacy combat wrapper should delegate through the same dispatcher once');
  assertEqual(seen[1].source, 'combat-targeting', 'Legacy combat wrapper should delegate through the combat target-picker command surface');
  assertEqual(seen[1].targetIds[0], 'enemy-combat-panel-dispatch', 'Legacy combat wrapper should resolve the same target id before dispatch');
});

