  App.party = [player, ally];
  App.creatures = [enemy];
  App.combatState = {
    active: true,
    round: 1,
    currentTurn: 0,
    processing: false,
    turnQueue: [
      { unit: player, initiative: 20 },
      { unit: ally, initiative: 10 },
      { unit: enemy, initiative: 5 }
    ],
    syncActions: []
  };
  App.activeActor = player;
  App.syncSelection = {
    active: true,
    phase: 'participants',
    actorId: 'sync-role-player',
    participantIds: ['sync-role-player', 'sync-role-ally'],
    type: 'sync_fight'
  };
