test('Structures expose enter action and create persistent interiors', () => {
  const { App, elements } = loadAppForCombat(() => 1);
  const player = makeUnit('You');
  App.player = player;
  App.party = [player];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [], structureSpawned: true }]]);
  App.updateLanguage('es');
  App.enterStructure();
  assertEqual(App.log[App.log.length - 1].text, 'No hay una estructura para entrar aqui.', 'Missing-structure feedback should localize');
  App.inventory = [{ id: 'pack-coin', name: 'Old Coin' }];
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [], items: [{ id: 'ground-herb', name: 'Healing Herb' }], structure: 'cabin', structureSpawned: true }]]);
  const context = App._centerTileContext();
  assertContains(context.title, 'Cabin', `Structure center context should include structure title. Got ${context.title}`);
  assertContains(App._contextActionKeys().join(','), 'enter', 'Structure center context should include enter action key');
  assertContains(App._renderContextActions(), 'App.enterStructure()', 'Structure center context should generate enter action');
  App.showExplorationActions();
  assertNotContains(elements.get('desktop-context-belt').innerHTML, 'App.showInventory()', 'Structure context belt should not expose carried inventory');
  App.enterStructure();
  assertEqual(App.inInterior, true, 'Entering structure should switch to interior mode');
  assertEqual(App.log[App.log.length - 1].text, 'Entraste en Cabin.', 'Enter structure feedback should localize');
  assertEqual(Object.keys(App.activeInterior.tiles).length, 25, 'Structure interior should be a persistent 5x5 map');
  assert(App.worldMap.get('0,0').interior, 'Interior should be stored on overworld tile for persistence');
  assertEqual(App.worldMap.get('0,0').items[0].name, 'Healing Herb', 'Entering a structure should preserve ground items instead of copying carried inventory');
  assertContains(App._contextActionKeys().join(','), 'exit', 'Interior center context should include exit action key');
  assertContains(App._renderContextActions(), 'App.exitStructure()', 'Interior center context should generate exit action');
  assertNotContains(App._renderContextActions(), 'App.enterStructure()', 'Interior center context should not keep stale enter action');
});

test('Moving between tiles does not copy carried inventory into ground items', () => {
  const { App } = loadAppForCombat(() => 1);
  const player = makeUnit('You');
  App.player = player;
  App.party = [player];
  App.inventory = [{ id: 'pack-coin', name: 'Old Coin' }];
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'forest';
  App.mode = App.GAME_MODE.NORMAL;
  App.worldMap = new Map([
    ['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [], items: [{ id: 'ground-herb', name: 'Healing Herb' }] }],
    ['1,0', { x: 1, y: 0, biome: 'forest', explored: true, description: 'A saved clearing.', hasLandmark: false, creatures: [], items: [] }]
  ]);
  App.exploredTiles = new Set(['0,0', '1,0']);

  App.move(1, 0);

  const originItems = App.worldMap.get('0,0').items || [];
  assertEqual(originItems.length, 1, 'Leaving a tile should preserve its existing ground item count');
  assertEqual(originItems[0].name, 'Healing Herb', 'Leaving a tile should keep ground items separate from carried inventory');
  assertEqual(App.inventory[0].name, 'Old Coin', 'Moving should leave carried inventory on the player');
  assertEqual(App.getTileDelta(0, 0).items[0].name, 'Healing Herb', 'Persisted tile delta should keep ground items separate from carried inventory');
});

test('Composer and stage presence expose tile-local item pickup', () => {
  const { App, elements } = loadAppForCombat(() => 1);
  const player = makeUnit('You');
  let autoSaveCalls = 0;
  App.player = player;
  App.party = [player];
  App.inventory = [];
  App.autoSave = () => { autoSaveCalls += 1; };
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'forest';
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, description: 'A saved clearing.', creatures: [], items: [{ id: 'ground-herb', name: 'Healing Herb' }] }]]);

  const context = App._centerTileContext();
  assertContains(context.description, 'A saved clearing.', 'Center context should keep the tile prose');
  assertNotContains(context.description, 'Items here: Healing Herb.', 'Center context should not duplicate tile-local item presence');
  App.renderCenterPresence();
  assertContains(elements.get('desktop-presence-rail').innerHTML, 'Healing Herb', 'Desktop presence rail should name tile-local items');
  assertNotContains(elements.get('center-presence').innerHTML, 'Healing Herb', 'Center stage token should not duplicate named item presence');
  assertContains(App._renderContextActions(), 'App.takeTileItems()', 'Composer belt should expose tile-local pickup');
  assertNotContains(App._renderContextActions(), 'App.showInventory()', 'Tile-local pickup should not expose carried inventory in the composer');

  assertEqual(App.takeTileItems(), true, 'Taking tile items should report a handled action');
  assertEqual(App.inventory.length, 1, 'Tile-local pickup should move the item into carried inventory');
  assertEqual(App.inventory[0].name, 'Healing Herb', 'Tile-local pickup should preserve item identity');
  assertEqual(App.worldMap.get('0,0').items.length, 0, 'Tile-local pickup should remove the item from the ground');
  assertNotContains(App._renderContextActions(), 'App.takeTileItems()', 'Tile-local pickup should disappear after the ground is empty');
  assertContains(App.log[App.log.length - 1].text, 'Picked up Healing Herb.', 'Tile-local pickup should log the item transfer');
  assertEqual(autoSaveCalls, 1, 'Tile-local pickup should autosave changed world and inventory state');
});

