    App.player = player;
    App.party = [player];
    App.creatures = [target];
    App.location = { x: 4, y: -2 };
    App.combatState.active = true;
    App.combatState.round = 3;
    App.combatState.currentTurn = 1;
    App.dayCount = 2;
    App.timeHour = 21;
    App.nextTurn = function() {};
    App.executeActionAgainstTarget('fight', player, target);
