  const player = makeUnit('You', { id: 'player-1', CPun: 80, MPun: 100, CPle: 25, MPle: 100, hunger: 45, maxHunger: 90 });
  const ally = makeUnit('Ally', { id: 'ally-1', CPun: 999, MPun: 100, CPle: -5, MPle: 100 });
