  assertContains(allyCard, 'data-selection-mode="act-actor" data-selection-state="selected" data-command-slot="actor"', 'Selected desktop actor control should identify the actor slot');
  assertContains(allyCard, 'aria-label="Remove Ally from actors"', 'Selected desktop actor control should advertise remove semantics');
