test('Active auto-save slot cannot be deleted during a live run', async () => {
  const { App, elements, storage } = loadAppForCombat(() => 0.5, { confirm: true });
  const deleted = [];
  App._dbDelete = async (_store, key) => { deleted.push(key); };
  App.player = makeUnit('You');
  App.party = [App.player];
  App.activeSlot = 'slot2';
  App.saveManagerMode = 'load';
  storage.set('yaw-last-slot', 'slot2');
  storage.set('yaw-save-time-slot2', '1710000000000');

  App.renderSaveManager('load');
  const html = elements.get('save-manager').innerHTML;
  assertContains(html, 'Current auto-save slot: delete is locked while this run is active.', 'Active slot hint should explain why delete is locked');
  assertContains(html, 'Delete locked during live run', 'Active slot action summary should not advertise direct delete');
  assertContains(html, 'Cannot delete Slot 2 while this run is using it for auto-save. Quit to the main menu before deleting it.', 'Disabled delete control should explain the live-run guard');
  assertContains(html, 'disabled aria-disabled="true"', 'Active auto-save delete control should be disabled while playing');
  assertNotContains(html, "App.deleteSlot('slot2')", 'Active auto-save delete control should not wire a delete handler while playing');

  const deletedActive = await App.deleteSlot('slot2');
  assertEqual(deletedActive, false, 'Deleting the active auto-save slot should be rejected during a live run');
  assertEqual(deleted.length, 0, 'Rejected active-slot delete should not remove data');
  assert(!App.pendingConfirm, 'Rejected active-slot delete should not open confirmation');
  assertEqual(App.activeSlot, 'slot2', 'Rejected active-slot delete should keep the current auto-save slot');
  assertEqual(App.saveManagerStatus.message, 'Cannot delete Slot 2 while this run is using it for auto-save. Quit to the main menu before deleting it.', 'Rejected active-slot delete should explain the policy in the save manager');
});

test('Save slot metadata normalizes stored and requested slot names', async () => {
  const syncCase = loadAppForCombat(() => 0.5);
  const dbGets = [];
  syncCase.App._dbGet = async (_store, key) => {
    dbGets.push(key);
    return key === 'slot2' ? new Uint8Array([1]) : undefined;
  };
  syncCase.storage.set('yaw-last-slot', '../bad');
  syncCase.storage.set('yaw-last-save-time', '999');
  syncCase.storage.set('yaw-save-time-slot2', '1700000000000');
  const synced = await syncCase.App._syncLastSaveSlot();
  assertEqual(synced, 'slot2', 'Invalid last-slot metadata should fall back to the latest valid save slot');
  assertEqual(dbGets.includes('../bad'), false, 'Invalid last-slot metadata should never be used as an IndexedDB key');
  assertEqual(syncCase.storage.get('yaw-last-slot'), 'slot2', 'Fallback slot should replace invalid last-slot metadata');
  assertEqual(syncCase.storage.get('yaw-last-save-time'), '1700000000000', 'Fallback slot timestamp should replace stale last-save metadata');

  const saveCase = loadAppForCombat(() => 0.5);
  const putKeys = [];
  saveCase.App.player = makeUnit('You');
  saveCase.App.party = [saveCase.App.player];
  saveCase.App.screen = 'game';
  saveCase.App.activeSlot = '../../bad';
  saveCase.App._prepareSaveSnapshot = () => {};
  saveCase.App.persistWorldStateToMapStore = async () => {};
  saveCase.App._dbPut = async (_store, key) => { putKeys.push(key); };
  await saveCase.App.saveToSlot('../bad');
  assertEqual(putKeys.join(','), 'slot1', 'Invalid requested save slot should fall back before IndexedDB writes');
  assertEqual(saveCase.App.activeSlot, 'slot1', 'Invalid requested save slot should normalize activeSlot after save');
  assertEqual(saveCase.storage.get('yaw-last-slot'), 'slot1', 'Invalid requested save slot should persist only a valid last slot');
  assertEqual(saveCase.storage.has('yaw-save-time-../bad'), false, 'Invalid requested save slot should not create malformed timestamp keys');

  const newGameCase = loadAppForCombat(() => 0.5);
  newGameCase.storage.set('yaw-save-time-slot1', '1710000000000');
  newGameCase.App.activeSlot = 'slot2';
  const newGameStarted = newGameCase.App.beginNewGameInSlot('../bad');
  assertEqual(newGameStarted, false, 'Invalid requested new-game slot should be rejected instead of falling back');
  assert(!newGameCase.App.pendingConfirm, 'Invalid requested new-game slot should not open an overwrite confirmation');
  assertEqual(newGameCase.App.activeSlot, 'slot2', 'Invalid requested new-game slot should not change the active slot');
  assertEqual(newGameCase.storage.get('yaw-last-slot'), undefined, 'Invalid requested new-game slot should not persist fallback last-slot metadata');
  assertNotContains(newGameCase.document.getElementById('screen-create').style.display || '', 'flex', 'Invalid requested new-game slot should not open character creation');

  const deleteCase = loadAppForCombat(() => 0.5);
  const deleteKeys = [];
  deleteCase.storage.set('yaw-save-time-slot1', '1710000000000');
  deleteCase.storage.set('yaw-last-slot', 'slot1');
  deleteCase.App.activeSlot = 'slot2';
  deleteCase.App._dbDelete = async (_store, key) => { deleteKeys.push(key); };
  const deleteStarted = await deleteCase.App.deleteSlot('../bad');
  assertEqual(deleteStarted, false, 'Invalid requested delete slot should be rejected instead of falling back');
  assert(!deleteCase.App.pendingConfirm, 'Invalid requested delete slot should not open a delete confirmation');
  assertEqual(deleteKeys.length, 0, 'Invalid requested delete slot should not delete any IndexedDB key');
  assertEqual(deleteCase.storage.get('yaw-save-time-slot1'), '1710000000000', 'Invalid requested delete slot should preserve valid slot timestamps');
  assertEqual(deleteCase.storage.get('yaw-last-slot'), 'slot1', 'Invalid requested delete slot should preserve last-slot metadata');
  assertEqual(deleteCase.App.activeSlot, 'slot2', 'Invalid requested delete slot should not change the active slot');

  const loadCase = loadAppForCombat(() => 0.5);
  let loadCalled = false;
  loadCase.storage.set('yaw-last-slot', '../bad');
  loadCase.App.loadFromSlot = async () => { loadCalled = true; return true; };
  const loaded = await loadCase.App.loadLastPlayed();
  assertEqual(loaded, false, 'Invalid last-slot metadata should not continue into load');
  assertEqual(loadCalled, false, 'Invalid last-slot metadata should not call loadFromSlot');
  assertEqual(loadCase.storage.has('yaw-last-slot'), false, 'Invalid last-slot metadata should be cleared');
  assertEqual(loadCase.storage.has('yaw-last-save-time'), false, 'Invalid last-save metadata should be cleared with invalid lastSlot');
});

